"""Render the English engineering report from recorded evidence and actual code."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'artifacts/multisearch-prototype-report.html'
E = ROOT / 'artifacts/multisearch'

def load(name):
    return json.loads((E / name).read_text())

def esc(s):
    return html.escape(str(s))

def code(path, start=None, end=None):
    source = (ROOT / path).read_text()
    if start:
        source = source[source.index(start):]
    if end:
        source = source[:source.index(end)]
    return f'<div class="code-label">{esc(path)} · actual prototype source</div><pre><code>{esc(source.rstrip())}</code></pre>'

def table(headers, rows):
    return '<div class="table-wrap"><table><thead><tr>' + ''.join(f'<th>{esc(v)}</th>' for v in headers) + '</tr></thead><tbody>' + ''.join('<tr>'+''.join(f'<td>{esc(v)}</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'

def checks(result):
    return table(['Verification', 'Result', 'Evidence'], [(t['name'], 'PASS' if t['passed'] else 'FAIL', t['detail'] if isinstance(t['detail'], str) else json.dumps(t['detail'])) for t in result])

standalone, perf, limits, build = [load(p) for p in ['results.json', 'performance.json', 'limits-results.json', 'build-manifest.json']]
k8s = load('k8s-results.json') if (E/'k8s-results.json').exists() else None
k8s_ready = k8s and k8s.get('all_passed', False)
replicas = load('k8s-proxy-results.json') if (E/'k8s-proxy-results.json').exists() else []
phases = perf['phases']
p = next(x for x in phases if x['mode']=='parallel_search' and x['concurrent_groups']==1)
m = next(x for x in phases if x['mode']=='multisearch' and x['concurrent_groups']==1)
name = {'sequential_search':'Sequential Search', 'parallel_search':'Parallel Search', 'multisearch':'MultiSearch'}
performance_table = table(['Mode', 'Concurrent groups', 'Groups', 'RPCs', 'p50 ms', 'p95 ms', 'p99 ms', 'Logical searches/s', 'Errors'], [(name[x['mode']], x['concurrent_groups'], x['groups'], x['rpc_count'], f"{x['group_p50_ms']:.2f}", f"{x['group_p95_ms']:.2f}", f"{x['group_p99_ms']:.2f}", f"{x['logical_searches_per_s']:,.0f}", x['errors']) for x in phases])
cpu_table = table(['Mode', 'Concurrent groups', 'Measured wall s', 'Client CPU s / 1k searches', 'Server CPU s / 1k searches'], [(name[x['mode']],x['concurrent_groups'],f"{x['elapsed_s']:.3f}",f"{x['client_cpu_s']/x['logical_searches']*1000:.3f}",f"{x['server_cgroup_cpu_s']/x['logical_searches']*1000:.3f}") for x in phases])
